INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('sakleshpur', 1, 5, 'go',
  'Peak window. 14-28C dry. Coffee estates clear, Manjarabad Star Fort visible. Bisle viewpoint at year-cleanest.',
  'January is when Sakleshpur runs at its strongest. Daytime 16-28C, nights 14C, humidity 65 percent. Coffee plantations at their post-harvest clean (Arabica + Robusta harvest Nov-Dec). Manjarabad Fort and Bisle viewpoint at year-cleanest.',
  NULL,
  'Sakleshpur in January is the version Western Ghats regulars choose when Coorg and Chikmagalur feel overrun. Daytime 16-28C, nights 14C, humidity 65 percent, the post-harvest coffee estates clean and walkable. Sakleshpur sits at 950m elevation in the Hassan district, the most underrated of Karnataka''s coffee hill stations — slightly lower than Madikeri Coorg (1525m) and Chikmagalur (1090m) but tucked into the same Western Ghats wet zone with Bisle Reserve adjacent. The defining anchor is the Manjarabad Star Fort — built 1792 by Tipu Sultan to a French engineer''s plan, the only 8-pointed star-shaped fort in India, with a mirror-tank inside that reflected stars at night for astronomical observation (free entry, ASI-protected, 8am-5.30pm, 5km from Sakleshpur town off NH-75). Bisle Ghat viewpoint (35km west — the dramatic Western Ghats escarpment overlook into Pushpagiri Wildlife Sanctuary, sunrise spot par excellence) at year-cleanest.'
)
