INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('sakleshpur', 2, 5, 'go',
  'Driest month. 15-29C. Coffee estate walks clean. Manjarabad Fort and Bisle viewpoint year-cleanest.',
  'February is the cleanest weather window. Coffee estates pre-blossom dormant phase. Manjarabad Fort and Bisle viewpoint at peak visibility. Hotel rates ease 15 percent.',
  NULL,
  'Sakleshpur in February is the technical peak weather window before March coffee blossom. Rainfall under 10mm, daytime 17-29C, nights 15C, humidity 60 percent — the lowest of the year. The coffee plantations at the Hassan district''s 950m elevation are in their dormant pre-blossom phase — after the November-December Arabica harvest and before the March-April flowering window — the estates clean, the under-canopy plantation walks at year-cleanest underfoot. Operators: Tata Coffee, Coorg Wilderness Camp, Soma Estate, Heragu Estate plantation walks ₹500-1,200 per person, 2-hour walks with planter-guides explaining bean varieties (Arabica higher-altitude, Robusta lower-altitude), harvest cycles, parchment-coffee drying yards, traditional Kannada-Konkani planter cuisine lunches ₹600-1,000. The Manjarabad Star Fort (1792 Tipu Sultan, 8-pointed star to French engineer''s plan — the only star-shaped fort in India, mirror-tank inside that reflected the stars for astronomers at night, ASI-protected free entry, 8am-5.30pm) at year-cleanest visibility from the corner bastions.'
)
