INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('sakleshpur', 3, 5, 'go',
  'Coffee Blossom window opens. 17-30C. White carpet across estates for 7-10 days after pre-monsoon showers.',
  'March is the Coffee Blossom window. Pre-monsoon showers (15-30mm) trigger Arabica + Robusta white flowering across the estates — 7-10 day visual peak, weather-dependent. Estate walks at year-iconic. Lock plantation homestays 4-6 weeks ahead.',
  NULL,
  'Sakleshpur in March is when the year''s defining visual arrives. Daytime 18-30C, nights 17C, humidity climbing to 70 percent in the last fortnight, rainfall 30-60mm — the pre-monsoon showers that trigger the Coffee Blossom. The phenomenon: the first significant rainfall after the dry season prompts simultaneous flowering across the Western Ghats coffee belt; both Arabica (higher altitude, slower yield) and Robusta (lower altitude, hardier) flower simultaneously, producing a white-blossom carpet across thousands of hectares for a 7-10 day visual peak that is exceptionally weather-dependent. The blossom typically falls between March 5 and April 10 depending on rain timing; planters time the bloom by listening for the first thunderclap. Estate walks during the blossom run at year-iconic — Tata Coffee, Coorg Wilderness Camp, Soma Estate, Heragu Estate ₹600-1,500 per person, plantation lunches included for ₹800-1,200 add-on. Lock plantation homestays 4-6 weeks ahead — the bloom drives the year''s tightest accommodation window across Sakleshpur, Coorg, Chikmagalur.'
)
