INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('sakleshpur', 4, 4, 'go',
  'Coffee Blossom tail. 19-31C, humidity 75 percent. Blossom continues first 10 days then heat builds.',
  'April first 10 days extend the Coffee Blossom window. Last 20 days bring pre-monsoon heat plus thunderstorms. Manjarabad Fort and Bisle viewpoint workable dawn and dusk only. Hotel rates ease 15 percent post-blossom.',
  NULL,
  'Sakleshpur in April splits cleanly in two. The first 10 days extend March''s Coffee Blossom — the white-blossom carpet across Arabica and Robusta estates continues if pre-monsoon showers held through late March. Daytime 21-31C, nights 19C, humidity 75 percent. Tata Coffee, Coorg Wilderness Camp, Soma Estate, Heragu Estate plantation walks at year-tail-end of the iconic bloom visual (₹600-1,500 per person, 2-hour walks). By April 12-15 the blossom has set into fruit (the green coffee cherries that will ripen through November) and the year''s peak visual closes. The Manjarabad Star Fort (1792 Tipu Sultan, 8-pointed star plan by French engineer — the only star-shaped fort in India, ASI-protected free entry, 8am-5.30pm) at year-cleanest dawn-and-dusk visibility but mid-day climb workable only 6.30-9am and 5-7pm. Bisle Ghat viewpoint (35km west — Western Ghats escarpment overlook into Pushpagiri Wildlife Sanctuary) workable dawn-only — afternoon haze builds. Patla Betta, Jenukal Gudda viewpoint treks at dawn only. Vishu (April 14, Kerala spillover) brings a 2-3 day domestic bump.'
)
