INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('sakleshpur', 5, 3, 'wait',
  'Pre-monsoon. 20-32C humidity 80 percent. Pre-monsoon thunderstorms. Estate walks dawn-only.',
  'May is the late pre-monsoon window. Coffee Blossom finished, estate walks workable dawn-only. Pre-monsoon thunderstorms knock grid power. Hotel rates at year-low pre-monsoon.',
  'May runs hot, sticky on the Sakleshpur escarpment. Coffee blossom finished, estate walks compress to dawn-only, pre-monsoon thunderstorms knock grid power. October-March is dramatically better.',
  'Sakleshpur in May is the closing pre-monsoon month before the southwest current arrives in early-to-mid June. Daytime 22-32C, nights 21C, humidity 80 percent. The Coffee Blossom window has finished by May 1; the estates show green coffee cherries setting on the bushes (the November-December harvest now 6 months away). Pre-monsoon thunderstorms hit the third and fourth weeks — afternoon squalls that knock grid power 1-2 hours daily, drop temperatures 4-5 degrees temporarily, and raise humidity to 90 percent for the rest of the day. Plantation walks at Tata Coffee, Coorg Wilderness Camp, Soma Estate, Heragu Estate (₹500-1,200 per person, 2-hour walks) workable only 6.30-9am — afternoon walks become punishing. The Manjarabad Star Fort (1792 Tipu Sultan, 8-pointed star plan, ASI-protected free entry, 8am-5.30pm) climb workable 6.30-9am only. Bisle Ghat viewpoint (35km west) workable dawn only — visibility collapses past 9am as pre-monsoon haze thickens. Hotel rates at year-low pre-monsoon: Crystal Springs Plantation Resort ₹3-4.5k, Manjarun Plantation ₹2.3-3.5k, homestays ₹1.2-2k. The Bengaluru-Sakleshpur 220km drive on NH-75 still clean before monsoon. Push to October.'
)
