INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('sakleshpur', 11, 5, 'go',
  'Peak builds. 15-28C, rainfall under 80mm. Coffee harvest in full swing. Karnataka Rajyotsava Nov 1.',
  'November is the proper pivot to peak. Coffee harvest at full swing — pickers, drying yards, hulling at year-iconic. Karnataka Rajyotsava Nov 1. Hotel rates climb 20 percent.',
  NULL,
  'Sakleshpur in November is the year''s second-peak month with the Coffee Harvest in full swing. Rainfall drops under 80mm, daytime 17-28C, nights 15C, humidity dropping below 70 percent. The Arabica and Robusta harvest cycles run November-December — November is the cleaner month with picker-teams across all estates, parchment-coffee drying yards out, pulper-and-hulling demonstrations at year-iconic. Tata Coffee, Coorg Wilderness Camp, Soma Estate, Heragu Estate plantation walks at peak immersion — picker-team encounters, sun-dried-parchment yards, cupping sessions where the year''s green-coffee samples are tasted alongside planters (₹600-1,500 per person, 2-3 hour walks, plantation lunches ₹800-1,200 add-on). The Manjarabad Star Fort (1792 Tipu Sultan, 8-pointed star plan, ASI-protected free entry, 8am-5.30pm) at full clean visibility. Bisle Ghat viewpoint (35km west) at year-cleanest dawn photograph light. Patla Betta, Jenukal Gudda viewpoint treks at year-cleanest dry-trail conditions. Karnataka Rajyotsava (November 1, 1956 state formation under States Reorganisation Act) sees cultural programmes.'
)
