INSERT INTO destination_months (destination_id, month, score, verdict, note, why_go, why_not, prose_lead)
VALUES ('sakleshpur', 12, 5, 'go',
  'Peak season. 14-28C dry. Christmas-NYE rates 1.8x. Coffee harvest tail. Lock plantation homestays 4-6 weeks ahead.',
  'December is when Sakleshpur runs at full capacity. Christmas-NYE rates 1.8x normal. Coffee harvest tail (early Dec). Plantation walks at full immersion. Lock plantation homestays 4-6 weeks ahead.',
  NULL,
  'Sakleshpur in December is the operational peak for the coffee-plantation-and-hill-station year. Daytime 16-28C, nights 14C, rainfall under 30mm. The Christmas-NYE corridor (December 22 to January 5) sees rates run 1.8x the November baseline: Crystal Springs Plantation Resort ₹5.5-8k, Manjarun Plantation ₹4.5-6.5k, homestays ₹2.2-3.5k. The Coffee Harvest tail-end runs through early-to-mid December — the Robusta harvest finishes by late November but Arabica picking extends into December, the parchment-coffee drying yards at full capacity, pulper-and-hulling operations 7 days a week. Tata Coffee, Coorg Wilderness Camp, Soma Estate, Heragu Estate plantation walks at year-iconic immersion (₹600-1,500 per person, 2-3 hour walks with planter-guides, lunches ₹800-1,200). The Manjarabad Star Fort (1792 Tipu Sultan, 8-pointed star plan by French engineer — the only star-shaped fort in India, ASI-protected free entry, 8am-5.30pm) at year-cleanest weekday visibility — go on a weekday to avoid the Christmas-NYE weekend traffic surge. Bisle Ghat viewpoint (35km west) at peak dawn-photograph light. Patla Betta, Jenukal Gudda viewpoint treks at year-cleanest dry-trail conditions.'
)
